from collections import deque

def max_total_score(n, scores):
    dp = deque([-scores[0]])
    for i in range(1, n):
        new_dp = deque()
        for j in range(len(dp)):
            if score_to_add := dp[j] + scores[i]:
                new_dp.append(score_to_add)
            if score_to_subtract := dp[j] - scores[i]:
                new_dp.appendleft(score_to_subtract)
        dp.extendleft(new_dp)
    return max(dp)

