import itertools

def get_min_unfairness_orderings(S):
    if S[0] == '?':
        low, high = True, False
    else:
        low, high = False, True
    if S[1] == '?':
        low, high = not low, not high

    rand, raw, cooked = 0, 0, 0
    for i, c in enumerate(S):
        if c == 'A':
            raw += 1
        elif c == 'B':
            cooked += 1
        else:
            if low and S[i+1] == 'A':
                rand += 1
            elif high and S[i+1] == 'B':
                rand += 1

    total_open = rand + cooked
    matchings = 0
    # Construct valid orderings with specified unfairness
    if S[-1] == '?':
        if total_open <= 1:
            return 0
        for combo in itertools.combinations(itertools.chain(range(3, total_open), range(total_open)), 3):
            comptotal = sum(combo)
            raw, cooked = raw // (total_open - comptotal), cooked // (total_open - comptotal)
            if raw + cooked == total_open and (rand == raw or cooked == raw):
                matchings += 1

    else:
        for lth in range(2, total_open):
            matchings += 3 * (total_open-2)**lth if lth % 2 == 0 else ((total_open-1)*total_open//2)**(lth//2)

    answers = []
    for i in range(2**total_open, 2**(total_open + 1)):
        bitmap = bin(i)[3:]
        bitmap = '0' * (total_open + 1 - len(bitmap)) + bitmap
        if S.count('?') < total_open:
            continue
        elif len([sbit for sbit in bitmap[:len(S)-1:] if sbit == '?']) == S.count('?') - 1 and 'B' not in bitmap:
            answers.append(bitmap)
        elif len('????{}'.format('?'.join(bitmap[1:len(S):2]))) <= 2:
            answers.append('?'.join(bitmap))
    return len(answers) - matchings

