def minimize_swaps(a):
    n = len(a)
    swaps = 0
    okay = [0] * n
    i = n // 2
    while i != 0:
        if a[(i - 1) * 2] > a[(i - 1) * 2 + 1]:
            if okay[(i - 1) * 2] == 1:
                swaps += okay[(i - 1) * 2]
                okay[(i - 1) * 2] = 0
            else:
                okay[(i - 1) * 2] = 1
        if a[i * 2] < a[i * 2 + 1]:
            if okay[i] == 1:
                swaps += okay[i]
                okay[i] = 0
            else:
                okay[i] = 1
        i //= 2
    return swaps

