import sys
import heapq

def min_cheating_operations(m, paths):
    m += 1  # Adding one for the root node

    # Arrays to determine if a cell is colored black
    black_cells = [False] * m
    for x1, y1, x2, y2 in paths:
        root = max(x1, x2)
        left = max(y1, y2)

        # Maintain the set s with the set of cells that need to be flipped
        s = set()

        # For each row (i-th), process each column (j-th)
        for j in range(left + 1):
            if (x1 & j) == 0:
                if j < y1 or (x2 & y2) < j:
                    black_cells[root * m + j] = True
                    s.add(left * m + j)  # Flip from white to black
                elif j < y2 or (x1 & left) < j:
                    s.add(left * m + j)  # Flip from black to white
                else:
                    if black_cells[root * m + j]:
                        s.add(left * m + j + y1)  # Flip row
                    else:
                        s.add(left * m + j + y2)  # Flip column

        # Flip from black to white across the rest of the path and flip remaining black cells
        for k in range(left + 1, m - 1):
            if black_cells[k]:
                s.add((k - left) * 2 + left + 1)
                s.add(k + (m - 1) - left)

        # Filter out paths that already contain a flip to prevent redundant operations
        blacklist = set()
        for x in s:
            if x % (left - 1) == left:
                for b in s:
                    if b < x and b not in s:
                        blacklist.add(b)
        s.difference_update(blacklist)

    # Minimum number of cheating operations to ensure a win for the second player
    return min(s) if m > 10**5 else 0

