def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def solution(n, elements):
    size = 0
    max_skewness = 0
    subset = []

    elements.sort()
    i, j = 0, n - 1
    while i < j:
        if elements[i] == elements[j] == 0:
            i += 1
            j -= 1
        elif elements[i] > elements[j]:
            skewness = elements[i] - elements[j]
            if skewness > max_skewness:
                max_skewness = skewness
                subset = deque()
                if i != j:
                    subset.append(elements[j])
                while max_skewness:
                    subset.append(elements[i])
                    skewness += elements[i] - elements[j]
                    i -= 1
                    j -= 1
            if max_skewness == 0:
                break
        else:
            skewness = elements[j] - elements[i]
            if skewness > max_skewness:
                max_skewness = skewness
                subset = deque()
                if i != j:
                    subset.append(elements[i])
                while max_skewness:
                    subset.append(elements[j])
                    skewness += elements[j] - elements[i]
                    i += 1
                    j += 1
    return subset

