def find_minimum_x(a, b, p, q):
    x = (a + b) / 2
    while True:
        old_x = x
        old_f_x = abs(math.sin(p/q * math.pi * x))
        x = (a + b) / 2
        new_f_x = abs(math.sin(p/q * math.pi * x))
        if old_f_x >= new_f_x:
