        self.visited = {(0, 0): 0}
        self.q = [(0, 0, 0, 0)]
        while self.q:
            x, y, row, col = self.q.pop(0)
            for nx, ny in [(x+1, y), (x-1, y), (x, y+1), (x, y-1)]:
                if 0 <= nx < cols:
                    if not self.board[row][ny] ^ self.board[row][ny+1]:
                        next_color = 1
                        move_pos = [ny - dy for dy in (-1, 1)]
                        for k, n in enumerate([[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]):
                            if all((nx + d * n[k], ny + d * n[1-k]) in self.visited for d in move_pos):
                                next_color += self.board[row][move_pos[k] + ny] ^ self.board[row][move_pos[1-k] + ny]
                        self.board[row][ny] = next_color
                        self.visit((nx, ny), next_color)
                    else:
                        self.board[row][ny] = not self.board[row][ny]
                        self.visit((nx, ny), not self.board[row][ny])
