def bfs(graph, path, distance, visited, start):
    queue = deque([(start, 0)])
    visited[start] = True
    while queue:
        node, dist = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                prev = path[path.index(node) + 1]
                new_path = path[path.index(node) - 1]
                s = int(new_path[0:node] + prev + new_path[node:])
                s2 = int(prev + new_path[node - 1] + new_path)
                dist += min(abs(s - dist), abs(s2 - dist))
                path[path.index(node)] = new_path
                visited[neighbor] = True
                queue.append((neighbor, dist))

