import sys
from collections import deque

def bfs(queue, memo):
    while queue:
        node, length = queue.pop(0)
        min_length = sys.maxsize
        for i in range(length - 1, -1, -1):
            temp = length - i
            if temp % 3 == 0:
                if node < temp // 3:
                    min_length = min(min_length, memo[i] + temp // 3)
                elif temp % 2 == 0 and node < temp // 2:
                    min_length = min(min_length, memo[i] + temp // 2)
                elif temp % 2 != 0 and node < (temp - 1) // 2:
                    min_length = min(min_length, memo[i] + (temp - 1) // 2)

        memo[length] = min_length

def longest_good_run(sequence, starting_point, i, next_looper):
    previous_starting_point = starting_point
    for j in range(i, len(sequence)):
        if sequence[j] == next_looper:
            if sequence[previous_starting_point] == sequence[j]:
                break
            else:
                previous_starting_point = j
    return j

def find_good_run(n, iterate_length, valid_runs):
    queue, memo = deque(), [sys.maxsize for i in range(iterate_length)]

    for i in range(iterate_length):
        if sequence[(n - longest_good_run(sequence, n - 1, i, 'B')) + 1] == 'B':
            memo[i] = i + 1
        queue.append((n - longest_good_run(sequence, n - 1, i, 'B') + 1, i + 1))

    answer = sys.maxsize
    for length in reversed(range(1, min(iterate_length, n + 1))):
        memo[0] = min(memo[0], answer + length)
        bfs(queue, memo)
    for length in range(2, iterate_length):
        memo[0] = min(memo[0], answer + length)

    return memo[1]
