def solve_ternary_logic(expression):
    digits = '0123456789+-*/ '
    operators = digits[10:]

    def parse_expression(expression):
        if '+' in expression:
            return parse_expression(expression.split('+')[0]) + parse_expression(expression.split('+')[1])
        elif '-' in expression:
            return parse_expression(expression.split('-')[0]) - parse_expression(expression.split('-')[1])
        elif '(' in expression:
            return parse_expression(expression[:expression.index(')')])
        else:
            return int(expression)

    return parse_expression(expression).mod(1000000007)

