def find_min_x(a, b, p, q):
    left, right = a % q, b % q
    if left > right:
        left, right = left + q, right + q

    lo, hi = left, right + 1
    if lo > hi:
        lo = left
        hi = left + b - a

    while hi - lo > 1:
        mid = (lo + hi) // 2
        if f(mid) < f(mid + 1):
            lo = mid
        else:
